--
-- Table structure for table `ine_order_return`
--

DROP TABLE IF EXISTS `ine_order_return`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ine_order_return` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'from orders',
  `invoice_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'from invoices\r\n',
  `serial_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'product serial number \r\n',
  `refund_amount` float NOT NULL,
  `refund_reference_number` int NOT NULL,
  `refund_date` datetime DEFAULT NULL,
  `image_1` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `image_2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `image_3` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `image_4` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `image_5` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `record_status` int NOT NULL DEFAULT '1' COMMENT '1 pending \r\n2 approved',
  `return_status` int NOT NULL DEFAULT '1',
  `status` int NOT NULL DEFAULT '1' COMMENT '1 active \r\n2\r\ndeleted',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
