--
-- Table structure for table `ine_orders`
--

DROP TABLE IF EXISTS `ine_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ine_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `serial_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `channel_mode` int DEFAULT NULL COMMENT '1 Online \r\n2 offline',
  `sales_user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_type` int DEFAULT NULL COMMENT '1.Deliver Now 2.Deliver at Home',
  `assisted_by` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `order_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `invoice_date` datetime DEFAULT NULL,
  `customer_id` int DEFAULT NULL,
  `address_id` int DEFAULT NULL,
  `base_amount` float DEFAULT NULL,
  `total_amount` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tax_amount` float DEFAULT NULL,
  `order_status` int DEFAULT '1' COMMENT '1.Pending 2.Placed 3.Packed 4.Shipped 5.Delivered 6.Cancelled',
  `payment_type` int DEFAULT NULL COMMENT '1.Cash 2.UPI 3.Credit/Debit',
  `payment_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `payment_gateway` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `payment_by_customer` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `payment_by_giftcard` float DEFAULT NULL,
  `giftcard_id` int DEFAULT NULL,
  `payment_status` int DEFAULT '1' COMMENT '1.Pending 2.Success 3.Failed',
  `affiliate_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `coupon_id` int DEFAULT NULL,
  `campaign_discount` double DEFAULT NULL,
  `record_status` int DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `total_items` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

